'use strict';

var assert = require('assert');

var TafClient = require('@taf/taf-rpc').client;
var TafConfigure = require('@taf/taf-config-parser');
var Notify = require('./NotifyProxy');

var client, servername;
var emptyfn = function() {};

var LEVEL = Notify.taf.NOTIFYLEVEL;

var init = function(tafConfig) {
        var config;

        assert(tafConfig || process.env.TAF_CONFIG, 'TAF_CONFIG is not in env and tafConfig not defined');

        if (tafConfig instanceof TafConfigure) {
                config = tafConfig;
        } else {
                if (typeof tafConfig === 'string') {
                        TafClient.initialize(tafConfig);
                        config = new TafConfigure();
                        config.parseFile(tafConfig);
                } else if (process.env.TAF_CONFIG) {
                        config = new TafConfigure();
                        config.parseFile(process.env.TAF_CONFIG);
                }
        }

        assert(config, 'tafConfig not instanceof taf-rpc.util.configure');

        assert(config.get('taf.application.server.app') && 
                config.get('taf.application.server.server'), 'app & server not found in configure file');

        client = TafClient.stringToProxy(Notify.taf.NotifyProxy, config.get('taf.application.server.notify', 'taf.tafnotify.NotifyObj'));
        servername = config.get('taf.application.server.app') + '.' + config.get('taf.application.server.server');
};

exports.init = init;

exports.report = function(message, id, server) {
        if (!client) {
                init();
        }

        if (!message) {
                return false;
        }

        if (!id && typeof id !== 'string') {
                id = process.pid;
        }

        client.reportServer(server || servername, id.toString(), message).catch(emptyfn).done();
        return true;
};

exports.notify = function(message, level, server) {
        if (!client) {
                init();
        }

        if (!message) {
                return false;
        }

        //notify not support now.
//        client.notifyServer(server || servername, typeof level === 'number' ? level : LEVEL.NOTIFYNORMAL, message).catch(emptyfn).done();
        return true;
};

exports.LEVEL = LEVEL;
